// Kiểm tra biến môi trường LÚC KHỞI ĐỘNG: lỗi sớm còn hơn lỗi lúc 3 giờ sáng
function loadEnv(env) {
  const errors = [];
  if (!env.DATABASE_URL) errors.push("thiếu DATABASE_URL");
  const port = Number(env.PORT ?? 3000);
  if (!Number.isInteger(port) || port < 1 || port > 65535) errors.push("PORT không hợp lệ");
  if (errors.length) throw new Error(errors.join("; "));
  return { databaseUrl: env.DATABASE_URL, port };
}

try { loadEnv({ PORT: "abc" }); } catch (e) { console.log(e.message); }
console.log(JSON.stringify(loadEnv({ DATABASE_URL: "postgres://x" })));

