function health(checks) {
  const bad = Object.entries(checks).filter(([, ok]) => !ok).map(([k]) => k);
  return bad.length === 0 ? { status: 200, body: "ok" } : { status: 503, body: bad.join(",") };
}
const a = health({ db: true, cache: true });
const b = health({ db: false, cache: true });
console.log(a.status + ":" + a.body + "," + b.status + ":" + b.body);
